import{_ as s,a0 as l,w as a,s as u,ao as d,I as r,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何找出Linux中內置模組的信息 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何找出Linux中內置模組的信息 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何找出Linux中內置模組的信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何找出Linux中內置模組的信息 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux","title":"Linux有問必答：如何找出Linux中內置模組的信息","tag":"201511","desc":""},"relativePath":"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux.md","filePath":"[post].md"}'),p={name:"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux.md"};function m(f,t,x,c,L,b){const o=l("Link");return a(),u("div",null,[t[13]||(t[13]=d(`<h1 id="linux有問必答-如何找出linux中內置模組的信息" tabindex="-1">Linux有問必答：如何找出Linux中內置模組的信息 <a class="header-anchor" href="#linux有問必答-如何找出linux中內置模組的信息" aria-label="Permalink to “Linux有問必答：如何找出Linux中內置模組的信息”">​</a></h1><blockquote><p><strong>提問</strong>：我想要知道Linux系統中內核內置的模組，以及每個模組有哪些參數。有什麼方法可以得到內置模組和設備驅動的列表，以及它們的詳細信息呢？</p></blockquote><p>現代Linux內核正在隨着時間變化而迅速增長，以支持大量的硬件、文件系統和網絡功能。在此期間，“可加載模組（loadable kernel modules，[LKM]）”的引入防止內核變得越來越臃腫，以及在不同的環境中靈活地擴展功能及硬件支持，而不必重新構建內核。</p><p>最新的Linux發行版的內核只帶了相對較小的“內置模組（built-in modules）”，其餘的特定硬件驅動或者自定義功能作為“可加載模組”來讓你選擇地加載或卸載。</p><p>內置模組被靜態地編譯進了內核。不像可加載內核模組可以動態地使用<code>modprobe</code>、<code>insmod</code>、<code>rmmod</code>、<code>modinfo</code>或者<code>lsmod</code>等命令地加載、卸載、查詢模組，內置的模組總是在啓動時就加載進了內核，不會被這些命令管理。</p><h3 id="找出內置模組列表" tabindex="-1">找出內置模組列表 <a class="header-anchor" href="#找出內置模組列表" aria-label="Permalink to “找出內置模組列表”">​</a></h3><p>要得到內置模組列表，運行下面的命令。</p><pre><code>$ cat /lib/modules/$(uname -r)/modules.builtin 
</code></pre><p><img src="https://farm1.staticflickr.com/697/21481933835_ef6b9c71e1_c.jpg" alt=""></p><p>你也可以用下面的命令來查看有哪些內置模組：</p><p><img src="https://farm6.staticflickr.com/5643/21295025949_57f5849c36_c.jpg" alt=""></p><h3 id="找出內置模組參數" tabindex="-1">找出內置模組參數 <a class="header-anchor" href="#找出內置模組參數" aria-label="Permalink to “找出內置模組參數”">​</a></h3><p>每個內核模組無論是內置的還是可加載的都有一系列的參數。對於可加載模組，<code>modinfo</code>命令可以顯示它們的參數信息。然而這個命令對內置模組沒有用。你會得到下面的錯誤。</p><pre><code>modinfo: ERROR: Module XXXXXX not found.
</code></pre><p>如果你想要查看內置模組的參數，以及它們的值，你可以在 <strong>/sys/module</strong> 下檢查它們的內容。</p><p>在 /sys/module目錄下，你可以找到內核模組（包含內置和可加載的）命名的子目錄。進入每個模組目錄，這裏有個“parameters”目錄，列出了這個模組所有的參數。</p><p>比如你要找出tcp_cubic（內核默認的TCP實現）模組的參數。你可以這麼做：</p><pre><code>$ ls /sys/module/tcp_cubic/parameters 
</code></pre><p>接着閲讀這個文件查看每個參數的值。</p><pre><code>$ cat /sys/module/tcp_cubic/parameters/tcp_friendliness 
</code></pre><p><img src="https://farm6.staticflickr.com/5639/21293886250_a199b9c8f7_c.jpg" alt=""></p><hr>`,22)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/find-information-builtin-kernel-modules-linux.html"},{default:i(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/find-information-builtin-kernel-modules-linux.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const g=s(p,[["render",m]]);export{T as __pageData,g as default};
